import sqlite3
from datetime import datetime

from agents import function_tool

DB_PATH = "calendar.db"


@function_tool
def reschedule_calendar_event(
    event_id: int, new_start: str, new_end: str, reason: str = ""
) -> dict:
    try:
        start_dt = datetime.fromisoformat(new_start)
        end_dt = datetime.fromisoformat(new_end)
    except ValueError as exc:
        return {"success": False, "error": f"Invalid datetime: {exc}"}

    if end_dt <= start_dt:
        return {"success": False, "error": "End must be after start"}

    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    try:
        row = conn.execute(
            "SELECT id, title, start_time, end_time FROM events WHERE id = ?",
            (event_id,),
        ).fetchone()
        if row is None:
            return {"success": False, "error": f"Event {event_id} not found"}

        conflict = conn.execute(
            "SELECT COUNT(*) FROM events WHERE id != ? AND start_time < ? AND end_time > ?",
            (event_id, end_dt.isoformat(), start_dt.isoformat()),
        ).fetchone()[0]

        conn.execute(
            "UPDATE events SET start_time = ?, end_time = ? WHERE id = ?",
            (start_dt.isoformat(), end_dt.isoformat(), event_id),
        )
        conn.execute(
            "INSERT INTO event_history (event_id, old_start, old_end, reason, changed_at) "
            "VALUES (?, ?, ?, ?, ?)",
            (
                event_id,
                row["start_time"],
                row["end_time"],
                reason,
                datetime.utcnow().isoformat(),
            ),
        )
        conn.commit()
    finally:
        conn.close()

    return {
        "success": True,
        "event_id": event_id,
        "title": row["title"],
        "previous": {"start": row["start_time"], "end": row["end_time"]},
        "current": {"start": start_dt.isoformat(), "end": end_dt.isoformat()},
        "overlapping_events": conflict,
        "reason": reason,
    }
